import {inspectResearchObj,RESEARCH_MESH_BYTES_LIMIT} from "./research-mesh-contract.js";

/**
 * Local study tool. Import the REAL OBJ generated by user's licensed MICA
 * Python installation. No MICA inference occurs in this static web page.
 */
export function setupResearchMeshImporter(){
  const $=id=>document.getElementById(id);
  const input=$("mica-obj-file"),download=$("mica-export-glb"),reset=$("mica-clear");
  const status=$("mica-import-status"),panel=$("mica-import-result"),viewport=$("mica-viewport");
  const metrics=$("mica-import-metrics");
  let runtime=null,sourceReport=null,loading=false,exporting=false,state="idle",generation=0;
  function say(message,statusCode){status.textContent=message;state=statusCode;}
  function metric(key,value){
    const row=document.createElement("div");row.className="metric-row";
    const title=document.createElement("strong"),text=document.createElement("span");
    title.textContent=key;text.textContent=String(value);row.append(title,text);return row;
  }
  function release(){
    const previous=runtime;runtime=null;sourceReport=null;
    previous?.dispose();
    panel.hidden=true;download.disabled=true;viewport.replaceChildren();metrics.replaceChildren();
  }
  function clear(){
    generation++;release();input.value="";loading=exporting=false;
    say("Import a local MICA mesh.obj produced by the official offline runner.","idle");
  }
  async function makeViewer(text){
    const T=await import("three");
    const [{OBJLoader},{OrbitControls}]=await Promise.all([
      import("three/addons/loaders/OBJLoader.js"),
      import("three/addons/controls/OrbitControls.js")
    ]);
    const parsed=new OBJLoader().parse(text);
    let meshCount=0;
    const geometries=[],materials=[];
    parsed.traverse(item=>{
      if(!item.isMesh)return;
      meshCount++;
      if(item.geometry.getAttribute("position")?.count===0)throw Error("Empty OBJ geometry.");
      item.geometry.computeVertexNormals();
      const mat=new T.MeshStandardMaterial({
        color:0xb8a2df,roughness:.83,metalness:0,side:T.DoubleSide,
        flatShading:false
      });
      item.material=mat;
      geometries.push(item.geometry);materials.push(mat);
    });
    if(meshCount<1)throw Error("No mesh was parsed from the OBJ.");
    // The official MICA demo exports coordinates in millimeters.
    parsed.scale.setScalar(.001);
    const rawBounds=new T.Box3().setFromObject(parsed);
    const size=rawBounds.getSize(new T.Vector3());
    const center=rawBounds.getCenter(new T.Vector3());
    parsed.position.sub(center);
    parsed.name="MICA_Research_Imported_Geometry";
    parsed.userData={
      claimedProvider:"MICA (user-provided; not verified)",
      modelInferenceInBrowser:false,
      units:"meters (MICA demo mm multiplied by 0.001)",
      texture:"none",
      rigged:false
    };
    const TScene=new T.Scene();
    const camera=new T.OrthographicCamera(-1,1,1,-1,.001,100);
    const range=Math.max(size.x,size.y,size.z,.01);
    camera.position.set(0,0,Math.max(.5,range*4));
    camera.lookAt(0,0,0);
    TScene.add(new T.HemisphereLight(0xd9e8ff,0x483259,2.3));
    const light=new T.DirectionalLight(0xffffff,2.4);
    light.position.set(2,3,6);TScene.add(light);TScene.add(parsed);
    const renderer=new T.WebGLRenderer({antialias:true,alpha:true,powerPreference:"low-power",preserveDrawingBuffer:false});
    renderer.setPixelRatio(Math.min(window.devicePixelRatio||1,1.5));
    renderer.setClearColor(0x141b2a,1);
    renderer.outputColorSpace=T.SRGBColorSpace;
    renderer.domElement.setAttribute("aria-label","Imported research head geometry (local, untextured)");
    const controls=new OrbitControls(camera,renderer.domElement);
    controls.enableDamping=false;controls.enablePan=false;
    controls.minZoom=.6;controls.maxZoom=4;
    const draw=()=>renderer.render(TScene,camera);
    controls.addEventListener("change",draw);
    viewport.replaceChildren(renderer.domElement);
    const resize=()=>{
      const w=Math.max(2,viewport.clientWidth),h=Math.max(2,viewport.clientHeight);
      const halfHeight=range*.72,halfWidth=halfHeight*w/h;
      camera.left=-halfWidth;camera.right=halfWidth;camera.top=halfHeight;camera.bottom=-halfHeight;
      camera.updateProjectionMatrix();renderer.setSize(w,h,false);draw();
    };
    const observer=new ResizeObserver(resize);observer.observe(viewport);
    resize();
    return {
      asset:parsed,
      render:draw,
      async exportGlb(){
        const {GLTFExporter}=await import("three/addons/exporters/GLTFExporter.js");
        const bytes=await new GLTFExporter().parseAsync(parsed,{binary:true,onlyVisible:true,trs:true});
        if(!(bytes instanceof ArrayBuffer)||new DataView(bytes).getUint32(0,true)!==0x46546c67){
          throw Error("GLTFExporter did not return valid binary glTF.");
        }
        return bytes;
      },
      dispose(){
        observer.disconnect();controls.removeEventListener("change",draw);controls.dispose();
        for(const g of geometries)g.dispose();
        for(const m of materials)m.dispose();
        renderer.dispose();renderer.forceContextLoss?.();renderer.domElement.remove();
      }
    };
  }
  async function load(file){
    const request=++generation;release();loading=true;download.disabled=true;
    if(!file){loading=false;return;}
    try{
      if(file.size<1||file.size>RESEARCH_MESH_BYTES_LIMIT||!file.name.toLowerCase().endsWith(".obj")){
        throw Error("Choose a nonempty .obj file smaller than 24 MB.");
      }
      say("Checking OBJ geometry (no internet upload)…","validating");
      const source=await file.text();
      const report=inspectResearchObj(source);
      if(request!==generation)return;
      panel.hidden=false;
      say("Loading official Three.js OBJLoader, camera and GPU viewer…","loading");
      const candidate=await makeViewer(source);
      if(request!==generation){candidate.dispose();return;}
      runtime=candidate;sourceReport=report;
      metrics.replaceChildren(
        metric("Input format","Wavefront OBJ from a user-selected local file"),
        metric("Claimed provider","MICA — unverified file provenance"),
        metric("Vertices",report.vertices),
        metric("Triangles",report.triangles),
        metric("Extent (mm)",report.extentMm.join(" × ")),
        metric("Viewer scale","mm → meters (×0.001)"),
        metric("Texture","None — MICA OBJ geometry is not an image-textured avatar"),
        metric("Rigging","None; no skin weights or animation")
      );
      download.disabled=false;
      say("Real user-supplied OBJ parsed and displayed: "+report.vertices+" vertices, "+report.triangles+" triangles. This site did NOT run MICA inference.","ready");
    }catch(error){
      if(request===generation){
        release();say("Import failed: "+(error?.message||String(error)),"error");
      }
    }finally{if(request===generation)loading=false;}
  }
  input.addEventListener("change",event=>void load(event.target.files?.[0]));
  reset.addEventListener("click",clear);
  download.addEventListener("click",async()=>{
    if(!runtime||exporting)return;
    exporting=true;download.disabled=true;
    say("Exporting imported untextured geometry to a separate GLB…","exporting");
    try{
      const bytes=await runtime.exportGlb();
      const url=URL.createObjectURL(new Blob([bytes],{type:"model/gltf-binary"}));
      const a=document.createElement("a");a.href=url;a.download="photo3d-mica-import-untextured.glb";
      document.body.append(a);a.click();a.remove();
      setTimeout(()=>URL.revokeObjectURL(url),1500);
      say("GLB exported from imported geometry; no texture, skeleton, or inferred hidden details added.","exported");
    }catch(error){say("GLB export failed: "+(error?.message||String(error)),"error");}
    finally{exporting=false;download.disabled=!runtime;}
  });
  addEventListener("pagehide",()=>{generation++;release();});
  return {
    clear,
    status:()=>({
      state,ready:!!runtime,loading,exporting,
      vertices:sourceReport?.vertices??0,triangles:sourceReport?.triangles??0,
      inferenceExecutedHere:false
    })
  };
}
